const H38_NUMERATOR_Y_ORDER =
  THETA3MINUS_H39_SHARED_DOMAIN_EVALUATOR_CONSTANTS.r43_source_shift - 1;

function assertFinitePositiveInteger(name, value) {
  const resolved = Number(value);
  if (!Number.isInteger(resolved) || resolved < 1) {
    throw new Error(`${name} must be a positive integer`);
  }
  return resolved;
}

function assertFinitePositiveNumber(name, value) {
  const resolved = Number(value);
  if (!Number.isFinite(resolved) || resolved <= 0) {
    throw new Error(`${name} must be a positive finite number`);
  }
  return resolved;
}

function numericInterval(name, interval) {
  if (!Array.isArray(interval) || interval.length !== 2) {
    throw new Error(`${name} must be a two-entry interval`);
  }
  const resolved = interval.map(Number);
  if (
    !Number.isFinite(resolved[0]) ||
    !Number.isFinite(resolved[1]) ||
    resolved[0] >= resolved[1]
  ) {
    throw new Error(`${name} must be a finite increasing interval`);
  }
  return resolved;
}

function numericOrderedInterval(name, interval) {
  if (!Array.isArray(interval) || interval.length !== 2) {
    throw new Error(`${name} must be a two-entry interval`);
  }
  const resolved = interval.map(Number);
  if (
    !Number.isFinite(resolved[0]) ||
    !Number.isFinite(resolved[1]) ||
    resolved[0] > resolved[1]
  ) {
    throw new Error(`${name} must be a finite ordered interval`);
  }
  return resolved;
}

function uniqueIncreasingSamples(samples) {
  return [...new Set(samples.map((sample) => Number(sample).toPrecision(15)))]
    .map(Number)
    .sort((left, right) => left - right);
}

function speedSamplesForLocalSubcover({ targetSpeedInterval, subcellCount }) {
  const [targetLeft, targetRight] = targetSpeedInterval;
  const width = targetRight - targetLeft;
  const localSamples = Array.from({ length: subcellCount + 1 }, (_, index) =>
    targetLeft + (width * index) / subcellCount
  );
  return uniqueIncreasingSamples([
    root.SPEED_RATIO_ENCLOSURE[0],
    ...localSamples,
    root.SPEED_RATIO_ENCLOSURE[1],
  ]);
}

function targetRowsForSubcellCount({
  targetSpeedInterval,
  subcellCount,
  rootSubdivisions,
}) {
  const artifact =
    buildOctahedralFoldAwareCrossBinaryTheta3minusSpeedDependentFoldPairFirstYGdThirtyEighthOrderPostUSuccessorCoefficientCertificate(
      {
        speedSamples: speedSamplesForLocalSubcover({
          targetSpeedInterval,
          subcellCount,
        }),
        rootSubdivisions,
      }
    );
  return localRowsForTargetInterval(
    artifact.thirty_eighth_order_post_u_successor_coefficient_rows,
    targetSpeedInterval
  );
}

function localRowsForTargetInterval(rows, targetSpeedInterval) {
  const [targetLeft, targetRight] = targetSpeedInterval;
  return rows.filter((row) => {
    const [left, right] = row.speed_interval.map(Number);
    return left >= targetLeft - 1e-12 && right <= targetRight + 1e-12;
  });
}

function branchRowFor(row, branch) {
  const branchRow = row.branch_rows.find(
    (candidate) => candidate.branch === branch
  );
  if (!branchRow) {
    throw new Error(`row ${row.cell_id} does not contain branch ${branch}`);
  }
  return branchRow;
}

function pressureDiagnosticForRow({
  context,
  row,
  branch,
  outerRadius,
  shiftedIndex,
  hFreezeStartIndexes,
}) {
  const branchRow = branchRowFor(row, branch);
  return computeH39AffineCenterHRowSensitivityDiagnosticCandidate({
    context,
    cell: cellFromCertificateRow(row),
    branch,
    hIntervals: hIntervalsFromBranchRow(branchRow, { hCount: 39 }),
    solveSlopeInterval: branchRow.h38_solve_slope_interval,
    outerRadius,
    shiftedIndex,
    hFreezeStartIndexes,
  });
}

function finitePositive(value) {
  return Number.isFinite(Number(value)) && Number(value) > 0;
}

function finiteNonnegative(value) {
  return Number.isFinite(Number(value)) && Number(value) >= 0;
}

function boundedUnitValue(value) {
  const resolved = Number(value);
  return Number.isFinite(resolved) && resolved >= 0 && resolved <= 1;
}

function finiteMaximum(values) {
  const finiteValues = values
    .filter((value) => value !== null && value !== undefined)
    .map(Number)
    .filter(Number.isFinite);
  return finiteValues.length > 0 ? Math.max(...finiteValues) : null;
}

function finiteMinimum(values) {
  const finiteValues = values
    .filter((value) => value !== null && value !== undefined)
    .map(Number)
    .filter(Number.isFinite);
  return finiteValues.length > 0 ? Math.min(...finiteValues) : null;
}

function intervalCoverSummary(intervals, targetInterval = null) {
  const orderedIntervals = intervals
    .map((interval) => numericInterval("interval cover entry", interval))
    .sort((left, right) => left[0] - right[0]);
  const positiveGaps = [];
  for (let index = 1; index < orderedIntervals.length; index += 1) {
    positiveGaps.push(
      Math.max(0, orderedIntervals[index][0] - orderedIntervals[index - 1][1])
    );
  }
  const maxPositiveGap =
    positiveGaps.length > 0 ? Math.max(...positiveGaps) : 0;
  const intervalHullValue =
    orderedIntervals.length > 0 ? intervalHull(orderedIntervals) : null;
  const resolvedTargetInterval =
    targetInterval === null ? null : numericInterval("targetInterval", targetInterval);
  const tolerance = 1e-12;
  return {
    interval_count: orderedIntervals.length,
    ordered_intervals: orderedIntervals,
    interval_hull: intervalHullValue,
    max_positive_gap: maxPositiveGap,
    intervals_contiguous_or_overlapping: maxPositiveGap <= tolerance,
    target_interval: resolvedTargetInterval,
    covers_target_interval:
      intervalHullValue !== null &&
      resolvedTargetInterval !== null &&
      intervalHullValue[0] <= resolvedTargetInterval[0] + tolerance &&
      intervalHullValue[1] >= resolvedTargetInterval[1] - tolerance,
  };
}

function intervalMidpoint([left, right]) {
  return (Number(left) + Number(right)) / 2;
}

function intervalWidth([left, right]) {
  return Number(right) - Number(left);
}

function intervalAbsUpper([left, right]) {
  return Math.max(Math.abs(Number(left)), Math.abs(Number(right)));
}

function intervalAbsLower([left, right]) {
  const resolvedLeft = Number(left);
  const resolvedRight = Number(right);
  if (resolvedLeft <= 0 && resolvedRight >= 0) {
    return 0;
  }
  return Math.min(Math.abs(resolvedLeft), Math.abs(resolvedRight));
}

function divideIntervalsIfNonzero(numeratorInterval, denominatorInterval) {
  if (!Array.isArray(numeratorInterval) || !Array.isArray(denominatorInterval)) {
    return null;
  }
  const numerator = root.outwardInterval(
    numericOrderedInterval("numerator_interval", numeratorInterval)
  );
  const denominator = root.outwardInterval(
    numericOrderedInterval("denominator_interval", denominatorInterval)
  );
  if (intervalAbsLower(denominator) <= 0) {
    return null;
  }
  return root.divideIntervals(numerator, denominator);
}

function stableIntervalSign(interval) {
  if (!Array.isArray(interval)) {
    return null;
  }
  if (intervalContainsZero(interval)) {
    return "contains-zero";
  }
  return signLabel(intervalMidpoint(interval));
}

function intervalEndpointMaxGap(left, right) {
  return Math.max(
    Math.abs(Number(left[0]) - Number(right[0])),
    Math.abs(Number(left[1]) - Number(right[1]))
  );
}

function intervalEndpointRelativeGap(left, right) {
  return (
    intervalEndpointMaxGap(left, right) /
    Math.max(1, intervalAbsUpper(left), intervalAbsUpper(right))
  );
}

function pointInterval(value) {
  return [value, value];
}

function pointCellAtMidpoint(cell) {
  return Object.fromEntries(
    Object.entries(cell).map(([key, interval]) => [
      key,
      pointInterval(intervalMidpoint(interval)),
    ])
  );
}

function hRowWidthProfileForRows({ rows, branch, hCount = 39 }) {
  return Array.from({ length: hCount }, (_, hIndex) => {
    const widths = rows.map((row) => {
      const branchRow = branchRowFor(row, branch);
      return intervalWidth(
        hIntervalsFromBranchRow(branchRow, { hCount })[hIndex]
      );
    });
    return {
      h_index: hIndex,
      max_width: Math.max(...widths),
      min_width: Math.min(...widths),
    };
  });
}

function hRowSignedTransportProfileForRows({ rows, branch, hCount = 39 }) {
  if (!Array.isArray(rows) || rows.length === 0) {
    return [];
  }
  const firstBranchRow = branchRowFor(rows[0], branch);
  const lastBranchRow = branchRowFor(rows[rows.length - 1], branch);
  const firstHIntervals = hIntervalsFromBranchRow(firstBranchRow, { hCount });
  const lastHIntervals = hIntervalsFromBranchRow(lastBranchRow, { hCount });
  return Array.from({ length: hCount }, (_, hIndex) => {
    const firstMidpoint = intervalMidpoint(firstHIntervals[hIndex]);
    const lastMidpoint = intervalMidpoint(lastHIntervals[hIndex]);
    const midpointDelta = lastMidpoint - firstMidpoint;
    return {
      h_index: hIndex,
      first_refined_midpoint: firstMidpoint,
      last_refined_midpoint: lastMidpoint,
      signed_refined_midpoint_delta: midpointDelta,
      direction_sign: Math.sign(midpointDelta) || 1,
    };
  });
}

function hRowAffineTransportProfileForRows({ rows, branch, hCount = 39 }) {
  if (!Array.isArray(rows) || rows.length !== 2) {
    throw new Error("one-noise h-row transport requires exactly two refined rows");
  }
  const [leftRow, rightRow] = rows
    .slice()
    .sort(
      (left, right) =>
        Number(left.speed_interval?.[0] ?? 0) -
        Number(right.speed_interval?.[0] ?? 0)
    );
  const leftBranchRow = branchRowFor(leftRow, branch);
  const rightBranchRow = branchRowFor(rightRow, branch);
  const leftHIntervals = hIntervalsFromBranchRow(leftBranchRow, { hCount });
  const rightHIntervals = hIntervalsFromBranchRow(rightBranchRow, { hCount });
  return Array.from({ length: hCount }, (_, hIndex) => {
    const leftMidpoint = intervalMidpoint(leftHIntervals[hIndex]);
    const rightMidpoint = intervalMidpoint(rightHIntervals[hIndex]);
    const centerCoefficient = (leftMidpoint + rightMidpoint) / 2;
    const directionCoefficient = (rightMidpoint - leftMidpoint) / 2;
    return {
      h_index: hIndex,
      h_i_minus: leftMidpoint,
      h_i_plus: rightMidpoint,
      center_coefficient_c_i: centerCoefficient,
      direction_coefficient_d_i: directionCoefficient,
      affine_formula: "h_i(xi)=c_i+xi*d_i",
    };
  });
}

function hRowAffineTransportProfilesByBranch({ rows, hCount = 39 }) {
  if (!Array.isArray(rows?.[0]?.branch_rows)) {
    throw new Error("refined rows must contain branch rows");
  }
  return Object.fromEntries(
    rows[0].branch_rows.map((branchRow) => [
      branchRow.branch,
      hRowAffineTransportProfileForRows({
        rows,
        branch: branchRow.branch,
        hCount,
      }),
    ])
  );
}

function hIntervalsForAffineTransportNoise({ transportProfile, noise }) {
  return transportProfile.map((profile) =>
    pointInterval(
      Number(profile.center_coefficient_c_i) +
        Number(noise) * Number(profile.direction_coefficient_d_i)
    )
  );
}

function hIntervalsForAffineTransportNoiseInterval({
  transportProfile,
  noiseInterval,
}) {
  const [noiseLeft, noiseRight] = noiseInterval;
  return transportProfile.map((profile) => {
    const left =
      Number(profile.center_coefficient_c_i) +
      Number(noiseLeft) * Number(profile.direction_coefficient_d_i);
    const right =
      Number(profile.center_coefficient_c_i) +
      Number(noiseRight) * Number(profile.direction_coefficient_d_i);
    return [Math.min(left, right), Math.max(left, right)];
  });
}

function speedMidpointXiCoordinate({ row, targetSpeedInterval }) {
  const [targetLeft, targetRight] = targetSpeedInterval;
  const targetWidth = targetRight - targetLeft;
  const speedFraction =
    (intervalMidpoint(row.speed_interval) - targetLeft) / targetWidth;
  return 4 * speedFraction - 2;
}

function speedIntervalXiInterval({ row, targetSpeedInterval }) {
  const [targetLeft, targetRight] = targetSpeedInterval;
  const targetWidth = targetRight - targetLeft;
  const mapped = row.speed_interval.map((speed) =>
    4 * ((Number(speed) - targetLeft) / targetWidth) - 2
  );
  return [Math.min(...mapped), Math.max(...mapped)];
}

function xiIntervalSpeedInterval({ xiInterval, targetSpeedInterval }) {
  const [targetLeft, targetRight] = targetSpeedInterval;
  const targetWidth = targetRight - targetLeft;
  const mapped = xiInterval.map(
    (xi) => targetLeft + ((Number(xi) + 2) / 4) * targetWidth
  );
  return [Math.min(...mapped), Math.max(...mapped)];
}

function intervalHull(intervals) {
  return [
    Math.min(...intervals.map((interval) => Number(interval[0]))),
    Math.max(...intervals.map((interval) => Number(interval[1]))),
  ];
}

function hIntervalsForAffineGraphPlusResidual({
  transportProfile,
  noiseInterval,
  residualProfile,
}) {
  const graphIntervals = hIntervalsForAffineTransportNoiseInterval({
    transportProfile,
    noiseInterval,
  });
  return graphIntervals.map((interval, hIndex) => {
    const residualAbs = Number(residualProfile?.[hIndex]?.max_abs_residual ?? 0);
    return [interval[0] - residualAbs, interval[1] + residualAbs];
  });
}

function solveLinearSystem(matrix, vector) {
  const size = vector.length;
  const augmented = matrix.map((row, rowIndex) => [
    ...row.map(Number),
    Number(vector[rowIndex]),
  ]);
  for (let column = 0; column < size; column += 1) {
    let pivotRow = column;
    for (let row = column + 1; row < size; row += 1) {
      if (
        Math.abs(augmented[row][column]) >
        Math.abs(augmented[pivotRow][column])
      ) {
        pivotRow = row;
      }
    }
    if (Math.abs(augmented[pivotRow][column]) < 1e-300) {
      throw new Error("polynomial fit linear system is singular");
    }
    if (pivotRow !== column) {
      [augmented[column], augmented[pivotRow]] = [
        augmented[pivotRow],
        augmented[column],
      ];
    }
    const pivot = augmented[column][column];
    for (let entry = column; entry <= size; entry += 1) {
      augmented[column][entry] /= pivot;
    }
    for (let row = 0; row < size; row += 1) {
      if (row === column) {
        continue;
      }
      const factor = augmented[row][column];
      for (let entry = column; entry <= size; entry += 1) {
        augmented[row][entry] -= factor * augmented[column][entry];
      }
    }
  }
  return augmented.map((row) => row[size]);
}

function fitPolynomialLeastSquares(points, degree) {
  const resolvedDegree = assertFinitePositiveInteger("degree", degree);
  if (!Array.isArray(points) || points.length < resolvedDegree + 1) {
    throw new Error("polynomial fit requires at least degree + 1 points");
  }
  const termCount = resolvedDegree + 1;
  const normalMatrix = Array.from({ length: termCount }, () =>
    Array.from({ length: termCount }, () => 0)
  );
  const normalVector = Array.from({ length: termCount }, () => 0);
  points.forEach((point) => {
    const xPowers = Array.from({ length: termCount }, (_, power) =>
      Math.pow(Number(point.x), power)
    );
    for (let row = 0; row < termCount; row += 1) {
      normalVector[row] += xPowers[row] * Number(point.y);
      for (let column = 0; column < termCount; column += 1) {
        normalMatrix[row][column] += xPowers[row] * xPowers[column];
      }
    }
  });
  return solveLinearSystem(normalMatrix, normalVector);
}

function polynomialValue(coefficients, x) {
  return coefficients.reduceRight(
    (accumulator, coefficient) => accumulator * Number(x) + Number(coefficient),
    0
  );
}

function polynomialDerivativeCoefficients(coefficients) {
  return coefficients
    .slice(1)
    .map((coefficient, index) => Number(coefficient) * (index + 1));
}

function lagrangeInterpolationPolynomialCoefficients(points) {
  if (!Array.isArray(points) || points.length === 0) {
    throw new Error("lagrange interpolation requires at least one point");
  }
  const coefficients = Array.from({ length: points.length }, () => 0);
  points.forEach((point, pointIndex) => {
    const xi = Number(point.x);
    const yi = Number(point.y);
    let basis = [1];
    let denominator = 1;
    points.forEach((otherPoint, otherIndex) => {
      if (otherIndex === pointIndex) {
        return;
      }
      const xj = Number(otherPoint.x);
      const nextBasis = Array.from({ length: basis.length + 1 }, () => 0);
      basis.forEach((coefficient, basisIndex) => {
        nextBasis[basisIndex] -= coefficient * xj;
        nextBasis[basisIndex + 1] += coefficient;
      });
      basis = nextBasis;
      denominator *= xi - xj;
    });
    basis.forEach((coefficient, coefficientIndex) => {
      coefficients[coefficientIndex] += (yi * coefficient) / denominator;
    });
  });
  return coefficients;
}

function lagrangeInterpolationDerivativeValue(points, x) {
  if (!Array.isArray(points) || points.length === 0) {
    throw new Error("lagrange interpolation derivative requires at least one point");
  }
  const evaluationPoint = Number(x);
  return points.reduce((total, point, pointIndex) => {
    const xi = Number(point.x);
    const yi = Number(point.y);
    let denominator = 1;
    points.forEach((otherPoint, otherIndex) => {
      if (otherIndex !== pointIndex) {
        denominator *= xi - Number(otherPoint.x);
      }
    });
    const numeratorDerivative = points.reduce(
      (sum, _otherPoint, omittedIndex) => {
        if (omittedIndex === pointIndex) {
          return sum;
        }
        const product = points.reduce((factor, factorPoint, factorIndex) => {
          if (factorIndex === pointIndex || factorIndex === omittedIndex) {
            return factor;
          }
          return factor * (evaluationPoint - Number(factorPoint.x));
        }, 1);
        return sum + product;
      },
      0
    );
    return total + (yi * numeratorDerivative) / denominator;
  }, 0);
}

function directedIntervalPolynomialValue({ coefficients, interval }) {
  const resolvedInterval = root.outwardInterval(
    numericOrderedInterval("interval", interval)
  );
  if (!Array.isArray(coefficients) || coefficients.length === 0) {
    return root.pointInterval(0);
  }
  let value = root.pointInterval(Number(coefficients[coefficients.length - 1]));
  for (let index = coefficients.length - 2; index >= 0; index -= 1) {
    value = root.addIntervals(
      root.multiplyIntervals(value, resolvedInterval),
      root.pointInterval(Number(coefficients[index]))
    );
  }
  return value;
}

function quadraticRoots({ a, b, c }) {
  if (Math.abs(a) < 1e-300) {
    return Math.abs(b) < 1e-300 ? [] : [-c / b];
  }
  const discriminant = b * b - 4 * a * c;
  if (discriminant < 0) {
    return [];
  }
  if (discriminant === 0) {
    return [-b / (2 * a)];
  }
  const root = Math.sqrt(discriminant);
  return [(-b - root) / (2 * a), (-b + root) / (2 * a)];
}

function polynomialCriticalPointsOnInterval(coefficients, interval) {
  const [left, right] = interval;
  const derivativeCoefficients = coefficients
    .slice(1)
    .map((coefficient, index) => Number(coefficient) * (index + 1));
  let roots = [];
  if (derivativeCoefficients.length === 1) {
    roots = [];
  } else if (derivativeCoefficients.length === 2) {
    const [constant, linear] = derivativeCoefficients;
    roots = Math.abs(linear) < 1e-300 ? [] : [-constant / linear];
  } else if (derivativeCoefficients.length === 3) {
    const [constant, linear, quadratic] = derivativeCoefficients;
    roots = quadraticRoots({
      a: quadratic,
      b: linear,
      c: constant,
    });
  } else if (derivativeCoefficients.length > 3) {
    throw new Error("polynomial interval ranges are implemented through degree 3");
  }
  return roots.filter(
    (rootPoint) =>
      Number.isFinite(rootPoint) &&
      rootPoint >= left &&
      rootPoint <= right
  );
}

function polynomialRangeOnInterval({ coefficients, interval }) {
  const resolvedInterval = numericInterval("interval", interval);
  const samplePoints = [
    resolvedInterval[0],
    resolvedInterval[1],
    ...polynomialCriticalPointsOnInterval(coefficients, resolvedInterval),
  ];
  const values = samplePoints.map((point) =>
    polynomialValue(coefficients, point)
  );
  return [Math.min(...values), Math.max(...values)];
}

function productValueForNodes(nodes, x) {
  return nodes.reduce(
    (product, node) => product * (Number(x) - Number(node)),
    1
  );
}

function productPolynomialCoefficientsForNodes(nodes) {
  return nodes.reduce(
    (coefficients, node) => {
      const nextCoefficients = Array.from(
        { length: coefficients.length + 1 },
        () => 0
      );
      coefficients.forEach((coefficient, index) => {
        nextCoefficients[index] -= Number(coefficient) * Number(node);
        nextCoefficients[index + 1] += Number(coefficient);
      });
      return nextCoefficients;
    },
    [1]
  );
}

function lagrangeProductIntervalForNodes({ nodes, interval }) {
  const xiInterval = root.outwardInterval(
    numericOrderedInterval("interval", interval)
  );
  return nodes.reduce(
    (productInterval, node) =>
      root.multiplyIntervals(
        productInterval,
        root.subtractIntervals(xiInterval, root.pointInterval(Number(node)))
      ),
    root.pointInterval(1)
  );
}

function productDerivativeValueForNodes(nodes, x) {
  return nodes.reduce((sum, _node, omittedIndex) => {
    const product = nodes.reduce(
      (factor, node, nodeIndex) =>
        nodeIndex === omittedIndex
          ? factor
          : factor * (Number(x) - Number(node)),
      1
    );
    return sum + product;
  }, 0);
}

function derivativeRootBetweenProductNodes({ nodes, left, right }) {
  let lower = Number(left);
  let upper = Number(right);
  let lowerValue = productDerivativeValueForNodes(nodes, lower);
  let upperValue = productDerivativeValueForNodes(nodes, upper);
  if (!Number.isFinite(lowerValue) || !Number.isFinite(upperValue)) {
    return null;
  }
  if (lowerValue === 0) {
    return lower;
  }
  if (upperValue === 0) {
    return upper;
  }
  if (lowerValue * upperValue > 0) {
    return null;
  }
  for (let iteration = 0; iteration < 100; iteration += 1) {
    const midpoint = (lower + upper) / 2;
    const midpointValue = productDerivativeValueForNodes(nodes, midpoint);
    if (!Number.isFinite(midpointValue)) {
      return null;
    }
    if (midpointValue === 0) {
      return midpoint;
    }
    if (lowerValue * midpointValue <= 0) {
      upper = midpoint;
      upperValue = midpointValue;
    } else {
      lower = midpoint;
      lowerValue = midpointValue;
    }
  }
  return (lower + upper) / 2;
}

function lagrangeProductEnvelopeOnInterval({ nodes, interval }) {
  const resolvedInterval = numericOrderedInterval("interval", interval);
  const sortedNodes = nodes
    .map(Number)
    .filter(Number.isFinite)
    .sort((left, right) => left - right);
  const samplePoints = [resolvedInterval[0], resolvedInterval[1]];
  for (let index = 0; index < sortedNodes.length - 1; index += 1) {
    const left = Math.max(sortedNodes[index], resolvedInterval[0]);
    const right = Math.min(sortedNodes[index + 1], resolvedInterval[1]);
    if (left >= right) {
      continue;
    }
    const rootPoint = derivativeRootBetweenProductNodes({
      nodes: sortedNodes,
      left,
      right,
    });
    if (
      Number.isFinite(rootPoint) &&
      rootPoint >= resolvedInterval[0] &&
      rootPoint <= resolvedInterval[1]
    ) {
      samplePoints.push(rootPoint);
    }
  }
  const rows = samplePoints.map((point) => {
    const product = productValueForNodes(sortedNodes, point);
    return {
      xi: point,
      product,
      abs_product: Math.abs(product),
    };
  });
  const maxRow = rows.reduce((best, row) =>
    Number(row.abs_product) > Number(best?.abs_product ?? -1) ? row : best,
  null);
  return {
    nodes: sortedNodes,
    interval: resolvedInterval,
    max_abs_product: maxRow?.abs_product ?? null,
    max_abs_product_location: maxRow?.xi ?? null,
    product_at_max_abs: maxRow?.product ?? null,
    candidate_rows: rows,
  };
}

function hRowPolynomialTransportProfileForRows({
  rows,
  branch,
  targetSpeedInterval,
  degree,
  hCount = 39,
}) {
  const resolvedDegree = assertFinitePositiveInteger("degree", degree);
  if (resolvedDegree > 3) {
    throw new Error("polynomial h-row graph diagnostic supports degree at most 3");
  }
  if (!Array.isArray(rows) || rows.length < resolvedDegree + 1) {
    throw new Error("polynomial h-row graph requires at least degree + 1 rows");
  }
  const sortedRows = rows
    .slice()
    .sort(
      (left, right) =>
        Number(left.speed_interval?.[0] ?? 0) -
        Number(right.speed_interval?.[0] ?? 0)
    );
  const rowSamples = sortedRows.map((row) => {
    const xiCoordinate = speedMidpointXiCoordinate({
      row,
      targetSpeedInterval,
    });
    const branchRow = branchRowFor(row, branch);
    const hMidpoints = hIntervalsFromBranchRow(branchRow, {
      hCount,
    }).map(intervalMidpoint);
    return {
      cell_id: row.cell_id,
      speed_interval: row.speed_interval,
      xi_coordinate: xiCoordinate,
      h_midpoints: hMidpoints,
    };
  });
  return Array.from({ length: hCount }, (_, hIndex) => {
    const fitPoints = rowSamples.map((sample) => ({
      x: sample.xi_coordinate,
      y: sample.h_midpoints[hIndex],
    }));
    const coefficients = fitPolynomialLeastSquares(fitPoints, resolvedDegree);
    const fitResiduals = fitPoints.map((point) => {
      const predicted = polynomialValue(coefficients, point.x);
      return {
        xi_coordinate: point.x,
        actual_h_midpoint: point.y,
        polynomial_graph_prediction: predicted,
        residual: point.y - predicted,
        abs_residual: Math.abs(point.y - predicted),
      };
    });
    return {
      h_index: hIndex,
      polynomial_degree: resolvedDegree,
      coefficients,
      coefficient_order: "ascending powers of xi",
      fit_max_abs_residual: Math.max(
        ...fitResiduals.map((residual) => residual.abs_residual)
      ),
      fit_residuals: fitResiduals,
    };
  });
}

function hRowPolynomialTransportProfilesByBranch({
  rows,
  targetSpeedInterval,
  degree,
  hCount = 39,
}) {
  if (!Array.isArray(rows?.[0]?.branch_rows)) {
    throw new Error("polynomial source rows must contain branch rows");
  }
  return Object.fromEntries(
    rows[0].branch_rows.map((branchRow) => [
      branchRow.branch,
      hRowPolynomialTransportProfileForRows({
        rows,
        branch: branchRow.branch,
        targetSpeedInterval,
        degree,
        hCount,
      }),
    ])
  );
}

function hIntervalsForPolynomialGraphInterval({
  transportProfile,
  noiseInterval,
}) {
  return transportProfile.map((profile) =>
    polynomialRangeOnInterval({
      coefficients: profile.coefficients,
      interval: noiseInterval,
    })
  );
}

function hIntervalsForPolynomialGraphPlusResidual({
  transportProfile,
  noiseInterval,
  residualProfile,
}) {
  const graphIntervals = hIntervalsForPolynomialGraphInterval({
    transportProfile,
    noiseInterval,
  });
  return graphIntervals.map((interval, hIndex) => {
    const residualAbs = Number(residualProfile?.[hIndex]?.max_abs_residual ?? 0);
    return [interval[0] - residualAbs, interval[1] + residualAbs];
  });
}

function hIntervalsForPolynomialGraphPlusIntervalResidual({
  transportProfile,
  noiseInterval,
  residualProfile,
}) {
  const graphIntervals = hIntervalsForPolynomialGraphInterval({
    transportProfile,
    noiseInterval,
  });
  return graphIntervals.map((interval, hIndex) => {
    const residualInterval =
      residualProfile?.[hIndex]?.residual_interval_hull ?? [0, 0];
    return [
      interval[0] + Number(residualInterval[0]),
      interval[1] + Number(residualInterval[1]),
    ];
  });
}

function hIntervalsForPolynomialGraphCorrelatedResidualPoint({
  transportProfile,
  noise,
  residualProfile,
  residualNoise,
  residualStartIndex = 0,
}) {
  return transportProfile.map((profile, hIndex) => {
    const residualInterval =
      residualProfile?.[hIndex]?.residual_interval_hull ?? [0, 0];
    const residualCenter =
      hIndex >= residualStartIndex ? intervalMidpoint(residualInterval) : 0;
    const residualRadius =
      hIndex >= residualStartIndex ? intervalWidth(residualInterval) / 2 : 0;
    return pointInterval(
      polynomialValue(profile.coefficients, noise) +
        residualCenter +
        Number(residualNoise) * residualRadius
    );
  });
}

function hIntervalsForPolynomialGraphResidualCentersWithH38VariantPoint({
  transportProfile,
  noise,
  residualProfile,
  h38ResidualInterval,
  h38Noise,
}) {
  return transportProfile.map((profile, hIndex) => {
    const residualInterval =
      hIndex === 38
        ? h38ResidualInterval
        : residualProfile?.[hIndex]?.residual_interval_hull ?? [0, 0];
    const residualCenter = intervalMidpoint(residualInterval);
    const residualRadius =
      hIndex === 38 ? intervalWidth(residualInterval) / 2 : 0;
    return pointInterval(
      polynomialValue(profile.coefficients, noise) +
        residualCenter +
        Number(h38Noise) * residualRadius
    );
  });
}

function hIntervalsForPolynomialGraphResidualCentersWithH38VariantInterval({
  transportProfile,
  noise,
  residualProfile,
  h38ResidualInterval,
  h38NoiseInterval,
}) {
  if (!Array.isArray(h38NoiseInterval) || h38NoiseInterval.length !== 2) {
    throw new Error("h38NoiseInterval must be a two-entry interval");
  }
  const resolvedH38NoiseInterval = h38NoiseInterval.map(Number);
  if (
    !Number.isFinite(resolvedH38NoiseInterval[0]) ||
    !Number.isFinite(resolvedH38NoiseInterval[1]) ||
    resolvedH38NoiseInterval[0] > resolvedH38NoiseInterval[1]
  ) {
    throw new Error("h38NoiseInterval must be a finite nondecreasing interval");
  }
  return transportProfile.map((profile, hIndex) => {
    const residualInterval =
      hIndex === 38
        ? h38ResidualInterval
        : residualProfile?.[hIndex]?.residual_interval_hull ?? [0, 0];
    const residualCenter = intervalMidpoint(residualInterval);
    if (hIndex !== 38) {
      return pointInterval(
        polynomialValue(profile.coefficients, noise) + residualCenter
      );
    }
    const residualRadius = intervalWidth(residualInterval) / 2;
    const graphCenter = polynomialValue(profile.coefficients, noise);
    return [
      graphCenter + residualCenter + resolvedH38NoiseInterval[0] * residualRadius,
      graphCenter + residualCenter + resolvedH38NoiseInterval[1] * residualRadius,
    ];
  });
}

function hIntervalsForPolynomialGraphIntervalResidualCentersWithH38VariantInterval({
  transportProfile,
  noiseInterval,
  residualProfile,
  h38ResidualInterval,
  h38NoiseInterval,
}) {
  if (!Array.isArray(h38NoiseInterval) || h38NoiseInterval.length !== 2) {
    throw new Error("h38NoiseInterval must be a two-entry interval");
  }
  const resolvedH38NoiseInterval = h38NoiseInterval.map(Number);
  if (
    !Number.isFinite(resolvedH38NoiseInterval[0]) ||
    !Number.isFinite(resolvedH38NoiseInterval[1]) ||
    resolvedH38NoiseInterval[0] > resolvedH38NoiseInterval[1]
  ) {
    throw new Error("h38NoiseInterval must be a finite nondecreasing interval");
  }
  return transportProfile.map((profile, hIndex) => {
    const residualInterval =
      hIndex === 38
        ? h38ResidualInterval
        : residualProfile?.[hIndex]?.residual_interval_hull ?? [0, 0];
    const residualCenter = intervalMidpoint(residualInterval);
    const graphInterval = directedIntervalPolynomialValue({
      coefficients: profile.coefficients,
      interval: noiseInterval,
    });
    if (hIndex !== 38) {
      return [
        Number(graphInterval[0]) + residualCenter,
        Number(graphInterval[1]) + residualCenter,
      ];
    }
    const residualRadius = intervalWidth(residualInterval) / 2;
    return [
      Number(graphInterval[0]) +
        residualCenter +
        resolvedH38NoiseInterval[0] * residualRadius,
      Number(graphInterval[1]) +
        residualCenter +
      resolvedH38NoiseInterval[1] * residualRadius,
  ];
  });
}

function hIntervalsForPolynomialGraphIntervalResidualCentersWithSharedVariantInterval({
  transportProfile,
  noiseInterval,
  residualProfile,
  h38ResidualInterval,
  h38NoiseInterval,
  sharedVariantHIndexes,
  sharedNoiseInterval,
}) {
  if (!Array.isArray(h38NoiseInterval) || h38NoiseInterval.length !== 2) {
    throw new Error("h38NoiseInterval must be a two-entry interval");
  }
  if (!Array.isArray(sharedNoiseInterval) || sharedNoiseInterval.length !== 2) {
    throw new Error("sharedNoiseInterval must be a two-entry interval");
  }
  const resolvedH38NoiseInterval = h38NoiseInterval.map(Number);
  const resolvedSharedNoiseInterval = sharedNoiseInterval.map(Number);
  if (
    !Number.isFinite(resolvedH38NoiseInterval[0]) ||
    !Number.isFinite(resolvedH38NoiseInterval[1]) ||
    resolvedH38NoiseInterval[0] > resolvedH38NoiseInterval[1] ||
    !Number.isFinite(resolvedSharedNoiseInterval[0]) ||
    !Number.isFinite(resolvedSharedNoiseInterval[1]) ||
    resolvedSharedNoiseInterval[0] > resolvedSharedNoiseInterval[1]
  ) {
    throw new Error("residual coordinate intervals must be finite nondecreasing intervals");
  }
  const sharedVariantHIndexSet = new Set(sharedVariantHIndexes ?? []);
  return transportProfile.map((profile, hIndex) => {
    const residualInterval =
      hIndex === 38
        ? h38ResidualInterval
        : residualProfile?.[hIndex]?.residual_interval_hull ?? [0, 0];
    const residualCenter = intervalMidpoint(residualInterval);
    const residualRadius = intervalWidth(residualInterval) / 2;
    const graphInterval = directedIntervalPolynomialValue({
      coefficients: profile.coefficients,
      interval: noiseInterval,
    });
    const residualNoiseInterval =
      hIndex === 38
        ? resolvedH38NoiseInterval
        : sharedVariantHIndexSet.has(hIndex)
          ? resolvedSharedNoiseInterval
          : null;
    if (residualNoiseInterval === null) {
      return [
        Number(graphInterval[0]) + residualCenter,
        Number(graphInterval[1]) + residualCenter,
      ];
    }
    return [
      Number(graphInterval[0]) +
        residualCenter +
        residualNoiseInterval[0] * residualRadius,
      Number(graphInterval[1]) +
        residualCenter +
        residualNoiseInterval[1] * residualRadius,
    ];
  });
}

function h39H38Y44FullResidualVectorPolynomialProfile({
  producerSamples,
  transportProfile,
}) {
  if (!Array.isArray(producerSamples) || !Array.isArray(transportProfile)) {
    return null;
  }
  const hCount = transportProfile.length;
  const samples = producerSamples
    .map((sample) => ({
      ...sample,
      xi_midpoint: Number(sample?.xi_midpoint),
    }))
    .filter(
      (sample) =>
        Number.isFinite(sample.xi_midpoint) &&
        Array.isArray(sample.h_intervals) &&
        sample.h_intervals.length === hCount &&
        sample.h_intervals.every(
          (interval) =>
            Array.isArray(interval) &&
            interval.length === 2 &&
            interval.every((value) => Number.isFinite(Number(value)))
        )
    );
  if (samples.length < 2 || hCount === 0) {
    return null;
  }
  const distinctXiValues = new Set(
    samples.map((sample) => sample.xi_midpoint.toPrecision(17))
  );
  if (distinctXiValues.size !== samples.length) {
    return null;
  }
  const residualMidpointRows = samples.map((sample) => ({
    cell_id: sample.cell_id,
    row_index: sample.row_index,
    xi_midpoint: sample.xi_midpoint,
    residual_midpoints: sample.h_intervals.map((hInterval, hIndex) => {
      const graphMidpoint = polynomialValue(
        transportProfile[hIndex].coefficients,
        sample.xi_midpoint
      );
      return intervalMidpoint(hInterval) - graphMidpoint;
    }),
  }));
  const residualCoefficientRows = Array.from({ length: hCount }, (_, hIndex) =>
    lagrangeInterpolationPolynomialCoefficients(
      residualMidpointRows.map((row) => ({
        x: row.xi_midpoint,
        y: row.residual_midpoints[hIndex],
      }))
    )
  );
  const sampleReplayResiduals = residualMidpointRows.map((row) => {
    const maxAbsReplayResidual = Math.max(
      ...row.residual_midpoints.map((residualMidpoint, hIndex) =>
        Math.abs(
          residualMidpoint -
            polynomialValue(
              residualCoefficientRows[hIndex],
              row.xi_midpoint
            )
        )
      )
    );
    return {
      cell_id: row.cell_id,
      row_index: row.row_index,
      xi_midpoint: row.xi_midpoint,
      max_abs_residual_midpoint_replay_error: maxAbsReplayResidual,
    };
  });
  return {
    provider_kind:
      "candidate-polynomial-h-row-full-residual-vector-xi-graph-provider",
    residual_vector_polynomial_degree: samples.length - 1,
    sample_count: samples.length,
    h_count: hCount,
    residual_coefficient_rows: residualCoefficientRows,
    max_sample_residual_midpoint_replay_error: Math.max(
      ...sampleReplayResiduals.map(
        (row) => row.max_abs_residual_midpoint_replay_error
      )
    ),
    sample_replay_residuals: sampleReplayResiduals,
  };
}

function hIntervalsForPolynomialGraphIntervalFullResidualVector({
  transportProfile,
  noiseInterval,
  fullResidualVectorProfile,
}) {
  return transportProfile.map((profile, hIndex) => {
    const graphInterval = directedIntervalPolynomialValue({
      coefficients: profile.coefficients,
      interval: noiseInterval,
    });
    const residualInterval = directedIntervalPolynomialValue({
      coefficients:
        fullResidualVectorProfile.residual_coefficient_rows[hIndex],
      interval: noiseInterval,
    });
    return root.addIntervals(graphInterval, residualInterval);
  });
}

function splitNumericInterval(interval, partitionCount) {
  const [left, right] = numericInterval("interval", interval);
  const resolvedPartitionCount = assertFinitePositiveInteger(
    "partitionCount",
    partitionCount
  );
  const width = (right - left) / resolvedPartitionCount;
  return Array.from({ length: resolvedPartitionCount }, (_, index) => [
    left + index * width,
    index === resolvedPartitionCount - 1
      ? right
      : left + (index + 1) * width,
  ]);
}

function candidateOnlyHRowProviderClaimBoundary() {
  return {
    certifies_shifted_R43_outer_bound: false,
    certifies_directed_rounded_shared_domain: false,
    certifies_continuous_polydisc_primitives: false,
    retained_branch: false,
  };
}

function componentDriftH36CoordinateLiftProviderBranchInput({
  branch,
  cellId,
  transportProfile,
  residualProfile,
  h38ResidualProfile,
  segmentInterval,
  h38NoiseInterval,
  h36NoiseInterval,
  solveSlopeInterval,
  sourceCoordinateGapRatio,
  collarHalfWidth,
}) {
  const hIntervals =
    hIntervalsForPolynomialGraphIntervalResidualCentersWithSharedVariantInterval({
      transportProfile,
      noiseInterval: segmentInterval,
      residualProfile,
      h38ResidualInterval: h38ResidualProfile.residual_interval_hull,
      h38NoiseInterval,
      sharedVariantHIndexes: [36],
      sharedNoiseInterval: h36NoiseInterval,
    });
  const dependencyTrace = [
    {
      dependency_kind: "component-drift-h36-coordinate-lift-collar",
      source: "selected residual-coordinate point-Jacobian source replay",
      active_h_indexes: [36],
      h38_noise_interval: h38NoiseInterval,
      h36_noise_interval: h36NoiseInterval,
      collar_half_width: collarHalfWidth,
      source_gap_to_target_ratio: sourceCoordinateGapRatio,
    },
  ];
  const providerKind =
    "candidate-component-drift-h36-coordinate-lift-collar-provider";
  const providerProvenance =
    "h39-y44-component-drift-h36-coordinate-lift-collar";
  return {
    branch,
    branchSign: root.branchSign(branch),
    hIntervals,
    solveSlopeInterval,
    dependency_preserving_h_row_provider: true,
    provider_kind: providerKind,
    providerKind,
    source_cell_id: cellId,
    sourceCellId: cellId,
    h_row_provider_kind: providerKind,
    h_row_provider_preserves_dependencies: true,
    preservesDependencies: true,
    h_row_provider_dependency_trace: dependencyTrace,
    hRowDependencyTrace: dependencyTrace,
    h_row_provider_source_cell_id: cellId,
    h_row_provider_provenance: providerProvenance,
    hRowProviderProvenance: providerProvenance,
    h_row_dependency_trace: dependencyTrace,
    h_row_dependency_witness: {
      witness_kind:
        "candidate-component-drift-h36-coordinate-lift-collar-provider",
      active_h_indexes: [36],
      h38_noise_interval: h38NoiseInterval,
      h36_noise_interval: h36NoiseInterval,
      collar_half_width: collarHalfWidth,
      h38_residual_interval: h38ResidualProfile.residual_interval_hull,
      h_count: hIntervals.length,
      claim_level:
        "segment-local provider-shaped branch input; not a two-branch directed-rounded H39 provider",
    },
    hRowDependencyWitness: {
      witness_kind:
        "candidate-component-drift-h36-coordinate-lift-collar-provider",
      active_h_indexes: [36],
      h38_noise_interval: h38NoiseInterval,
      h36_noise_interval: h36NoiseInterval,
      collar_half_width: collarHalfWidth,
      h38_residual_interval: h38ResidualProfile.residual_interval_hull,
      h_count: hIntervals.length,
      claim_level:
        "segment-local provider-shaped branch input; not a two-branch directed-rounded H39 provider",
    },
    h_row_provider_claim_boundary: candidateOnlyHRowProviderClaimBoundary(),
    hRowProviderClaimBoundary: candidateOnlyHRowProviderClaimBoundary(),
    h_row_provider_replay_kind:
      "h39-component-drift-h36-coordinate-lift-branch-input-replay",
    replayKind: "h39-component-drift-h36-coordinate-lift-branch-input-replay",
  };
}

